<?php
use App\Core\Csrf;
$symbol = match ($store['currency']) { 'USD' => 'US$', 'EUR' => '€', default => 'RD$' };
$customer = $portal['customer'];
$invoices = $portal['invoices'];
$orders = $portal['orders'];
$webOrders = $portal['web_orders'] ?? [];
$stats = $portal['stats'];
$customerName = trim((string) ($customer['nombre'] ?? 'Cliente')) ?: 'Cliente';
$initials = mb_strtoupper(mb_substr($customerName, 0, 1));
$date = static function (mixed $value): string {
    $value = trim((string) $value);
    if ($value === '') return '—';
    try { return (new DateTimeImmutable($value))->format('d/m/Y'); } catch (Throwable) { return $value; }
};
$invoiceNumber = static fn (array $invoice): string => (string) ($invoice['no_factura'] ?? $invoice['numero'] ?? $invoice['uid'] ?? '—');
$invoiceState = static fn (array $invoice): string => (string) ($invoice['estado_factura'] ?? $invoice['estado'] ?? 'COMPLETADA');
?>
