</main><footer class="footer">Portal privado de <?= e($store['store_name']) ?> · La información se obtiene del sistema de la tienda.</footer>
<script>(()=>{const tabs=document.querySelectorAll('[data-tab]'),panels=document.querySelectorAll('[data-panel]'),layout=document.querySelector('[data-layout]'),slug=<?= json_encode($store['slug']) ?>,wishKey=<?= json_encode('tmp-store-wishlist-'.$store['uid']) ?>,cartKey=<?= json_encode('tmp-store-cart-'.$store['uid']) ?>,symbol=<?= json_encode($symbol) ?>;function select(name){tabs.forEach(tab=>tab.classList.toggle('active',tab.dataset.tab===name));panels.forEach(panel=>panel.classList.toggle('active',panel.dataset.panel===name));layout.classList.toggle('hidden',!['purchases','profile'].includes(name));layout.classList.toggle('single',['purchases','profile'].includes(name));history.replaceState(null,'','#'+name);if(name==='favorites')renderFavorites()}tabs.forEach(tab=>tab.onclick=()=>select(tab.dataset.tab));const esc=value=>{const node=document.createElement('div');node.textContent=String(value??'');return node.innerHTML},attr=value=>esc(value).replace(/"/g,'&quot;'),money=value=>symbol+' '+Number(value||0).toLocaleString('es-DO',{minimumFractionDigits:2,maximumFractionDigits:2});let catalog=null;async function renderFavorites(){const box=document.querySelector('[data-favorites]');let ids=[];try{ids=JSON.parse(localStorage.getItem(wishKey)||'[]')||[]}catch(e){}document.querySelector('[data-favorite-count]').textContent=ids.length+' producto'+(ids.length===1?'':'s');if(!ids.length){box.innerHTML='<div class="empty">No has guardado productos todavía. <a class="action primary" href="/store/'+encodeURIComponent(slug)+'/categories">Explorar productos</a></div>';return}try{if(!catalog){const response=await fetch('/api/storefront/'+encodeURIComponent(slug)+'/products',{headers:{Accept:'application/json'}}),payload=await response.json();catalog=payload?.data?.products||[]}const products=ids.map(uid=>catalog.find(product=>String(product.uid)===String(uid))).filter(Boolean);if(!products.length){box.innerHTML='<div class="empty">Tus productos guardados ya no están disponibles.</div>';return}box.innerHTML=products.map(product=>'<article class="favorite-card"><a class="favorite-image" href="/store/'+encodeURIComponent(slug)+'/products/'+encodeURIComponent(product.uid)+'">'+(product.image?'<img src="'+attr(product.image)+'" alt="">':'□')+'</a><div class="favorite-body"><small>'+esc(product.category||'Producto')+'</small><h3>'+esc(product.name)+'</h3><strong>'+(product.price===null?'Consultar':money(product.price))+'</strong><div class="favorite-actions"><a href="/store/'+encodeURIComponent(slug)+'/products/'+encodeURIComponent(product.uid)+'">Ver</a><button type="button" data-favorite-add="'+attr(product.uid)+'">Agregar</button></div></div></article>').join('');box.querySelectorAll('[data-favorite-add]').forEach(button=>button.onclick=()=>{const product=products.find(item=>String(item.uid)===button.dataset.favoriteAdd);if(!product)return;let cart={};try{cart=JSON.parse(localStorage.getItem(cartKey)||'{}')||{}}catch(e){}const item=cart[product.uid]||{product,quantity:0};item.product=product;item.quantity=Math.min(99,Number(item.quantity||0)+1);cart[product.uid]=item;localStorage.setItem(cartKey,JSON.stringify(cart));button.textContent='Agregado ✓';setTimeout(()=>button.textContent='Agregar',1000)})}catch(e){box.innerHTML='<div class="empty">No pudimos cargar tus favoritos en este momento.</div>'}}const initial=location.hash.slice(1),allowed=['summary','orders','purchases','favorites','workshop','profile'];select(allowed.includes(initial)?initial:'summary')})();</script></body></html>
